Problem: AI-generation requests to /api/generate sometimes fail because the assistant output is not pure JSON (fenced code blocks, extra commentary, or the graph returned as a string). This leads to 502 responses and poor UX. We need to make the Pages Function more forgiving and provide improved debug output so the client can surface helpful error messages.

Task: Update functions/api/generate.js to:
- Strip markdown code fences (``` or ```json) before attempting to parse JSON.
- Attempt to parse the entire sanitized assistant text as JSON first.
- If that fails, fall back to extracting the first {...} JSON substring and parse that.
- If assistantJson.graph is a string, attempt to JSON.parse it as well.
- Preserve and expand debug fields returned on error: include sanitizedAssistantText and rawAssistantText (truncated) to aid debugging.
- Keep the existing CORS, OPENAI_API_KEY check, and model settings (model: 'gpt-4o-mini').
- Return 200 with { graph: graphObj } when parsed and validated (graphObj.nodes and graphObj.edges arrays exist), otherwise return helpful 502 payloads.

Replace the existing file at functions/api/generate.js with the following content (exact file contents must be used):

```javascript name=functions/api/generate.js url=https://github.com/tcoffin-creator/NapkinFlow/blob/main/functions/api/generate.js
export async function onRequest(context) {
  const { request, env } = context;
  const origin = request.headers.get('Origin') || '*';

  // CORS preflight
  if (request.method === 'OPTIONS') {
    return new Response(null, {
      status: 204,
      headers: {
        'Access-Control-Allow-Origin': origin,
        'Access-Control-Allow-Methods': 'POST, OPTIONS',
        'Access-Control-Allow-Headers': 'Content-Type, Authorization',
      },
    });
  }

  // Only allow POST here
  if (request.method !== 'POST') {
    return new Response(JSON.stringify({ error: 'Method not allowed' }), {
      status: 405,
      headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': origin },
    });
  }

  // Read JSON body
  let body;
  try {
    body = await request.json();
  } catch (err) {
    const text = await request.text();
    return new Response(JSON.stringify({ error: 'Invalid JSON body', bodyText: text }), {
      status: 400,
      headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': origin },
    });
  }

  const prompt = (body && body.prompt) ? String(body.prompt) : '';
  if (!prompt || prompt.trim().length === 0) {
    return new Response(JSON.stringify({ error: 'Missing prompt in request body' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': origin },
    });
  }

  // Read OpenAI key from env (Cloudflare Pages Functions expose secrets via context.env)
  const OPENAI_API_KEY = env?.OPENAI_API_KEY || process?.env?.OPENAI_API_KEY;
  if (!OPENAI_API_KEY) {
    return new Response(JSON.stringify({ error: 'Server misconfigured: OPENAI_API_KEY missing' }), {
      status: 500,
      headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': origin },
    });
  }

  // System prompt: instruct JSON-only output
  const systemPrompt = `You are a JSON-only generator. Given a plain-text workflow prompt, produce only valid JSON with a single top-level "graph" object:\n{\n  "graph": {\n    "nodes": [ { "id":"n1", "label":"Start", "type":"start" }, ... ],\n    "edges": [ { "from":"n1", "to":"n2", "label":"yes" }, ... ]\n  }\n}\nDo not include any extra text, comments, or markdown. If you cannot produce a graph, return { "graph": { "nodes": [], "edges": [] } }.`.trim();

  try {
    const openaiResp = await fetch('https://api.openai.com/v1/chat/completions', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${OPENAI_API_KEY}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model: 'gpt-4o-mini',
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: prompt },
        ],
        max_tokens: 1200,
        temperature: 0.2,
      }),
    });

    const raw = await openaiResp.text();

    if (!openaiResp.ok) {
      return new Response(JSON.stringify({ error: 'OpenAI API error', status: openaiResp.status, raw: raw.slice(0, 2000) }), {
        status: 502,
        headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': origin },
      });
    }

    // Try to parse wrapper response
    let parsedTop = null;
    try { parsedTop = JSON.parse(raw); } catch (e) { parsedTop = null; }

    // Extract assistant text if present
    let assistantText = '';
    if (parsedTop?.choices && parsedTop.choices[0]?.message?.content) {
      assistantText = parsedTop.choices[0].message.content;
    } else {
      assistantText = raw;
